<script setup lang="ts">
import { computed, reactive, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { ElMessage, ElMessageBox, type FormInstance } from "element-plus";
import { adminDelete, adminGet, adminPost, adminPut } from "../../../admin/api/adminClient";
import { teacherDelete, teacherGet, teacherPost, teacherPut, type TeacherClass } from "../../../teacher/teacherApi";
import { adminPath } from "../../../utils/adminPath";
import { formatDisplayDateTime } from "../../../lib/format";
import type { Course, CoursePage, CourseReport } from "../../../api/course";

type Publication = { id:number; title:string; status:string; displayOrder:number; problems:Array<unknown>; courseId:number; startTime?:string; endTime?:string };
type Source = { id:number; title:string; canPublish:boolean };
const route=useRoute();const router=useRouter();
const teacherMode=computed(()=>route.path.startsWith("/teacher/"));
const courseId=computed(()=>Number(route.params.courseId)||null);
const loading=ref(false);const error=ref("");const courses=ref<Course[]>([]);const course=ref<Course|null>(null);const publications=ref<Publication[]>([]);const report=ref<CourseReport|null>(null);const classes=ref<Array<{id:number;name:string}>>([]);const classFilter=ref<number|null>(null);const page=ref(1);const total=ref(0);const keyword=ref("");const dialogOpen=ref(false);const saving=ref(false);const editing=ref<Course|null>(null);const formRef=ref<FormInstance>();
const sourceDialog=ref(false);const sources=ref<Source[]>([]);const sourcePage=ref(1);const sourceTotal=ref(0);const selectedSource=ref<number|null>(null);const sourceLoading=ref(false);
const form=reactive({title:"",description:"",term:"",classIds:[] as number[],status:"ACTIVE" as Course["status"]});
const courseRows=computed(()=>courses.value);
const filteredStudents=computed(()=>report.value?.students.filter((student)=>!classFilter.value||student.classId===classFilter.value)??[]);
function url(path:string){return teacherMode.value?`/teacher${path}`:adminPath(path);}
function get<T>(path:string){return teacherMode.value?teacherGet<T>(path):adminGet<T>(path);}
function post<T>(path:string,body?:unknown){return teacherMode.value?teacherPost<T>(path,body):adminPost<T>(path,body);}
function put<T>(path:string,body?:unknown){return teacherMode.value?teacherPut<T>(path,body):adminPut<T>(path,body);}
function remove<T>(path:string){return teacherMode.value?teacherDelete<T>(path):adminDelete<T>(path);}
async function load(){loading.value=true;error.value="";course.value=null;publications.value=[];report.value=null;try{if(courseId.value){const [nextCourse,nextPublications,nextReport]=await Promise.all([get<Course>(`/api/admin/v1/courses/${courseId.value}`),get<Publication[]>(`/api/admin/v1/courses/${courseId.value}/practices`),get<CourseReport>(`/api/admin/v1/courses/${courseId.value}/report`)]);course.value=nextCourse;publications.value=nextPublications;report.value=nextReport;}else{const result=await get<CoursePage>(`/api/admin/v1/courses?page=${page.value}&pageSize=20&keyword=${encodeURIComponent(keyword.value.trim())}`);courses.value=result.list;total.value=result.total;}}catch(cause){error.value=cause instanceof Error?cause.message:"课程数据加载失败";}finally{loading.value=false;}}
function openForm(item?:Course){editing.value=item??null;Object.assign(form,item?{title:item.title,description:item.description??"",term:item.term??"",classIds:item.classIds??(item.classId?[item.classId]:[]),status:item.status}:{title:"",description:"",term:"",classIds:[],status:"ACTIVE"});dialogOpen.value=true;}
async function openEditor(item?:Course){try{classes.value=await get<TeacherClass[]|Array<{id:number;name:string}>>(teacherMode.value?"/api/teacher/v1/classes":"/api/admin/v1/classes");openForm(item);}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"班级列表加载失败");}}
async function saveCourse(){if(!formRef.value)return;try{await formRef.value.validate();}catch{return;}if(!form.title.trim()){ElMessage.warning("请输入课程名称");return;}if(form.status!=="DRAFT"&&!form.classIds.length){ElMessage.warning("请选择至少一个关联班级");return;}saving.value=true;try{const payload={...form,classIds:form.classIds};if(editing.value)await put(`/api/admin/v1/courses/${editing.value.id}`,payload);else await post("/api/admin/v1/courses",payload);ElMessage.success("课程已保存，关联班级学生自动加入");dialogOpen.value=false;await load();}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"课程保存失败");}finally{saving.value=false;}}
async function archive(item:Course){try{await ElMessageBox.confirm("归档后会停止新提交并保留历史记录。确认归档此课程？","归档课程",{type:"warning"});await remove(`/api/admin/v1/courses/${item.id}`);ElMessage.success("课程已归档");await load();}catch(cause){if(cause!=="cancel"&&cause!=="close")ElMessage.error(cause instanceof Error?cause.message:"归档失败");}}
async function loadSources(nextPage=1){sourceLoading.value=true;try{const result=await get<{total:number;list:Source[]}>(`/api/admin/v1/practices?page=${nextPage}&pageSize=50`);sources.value=result.list.filter((item)=>item.canPublish);sourceTotal.value=result.total;sourcePage.value=nextPage;selectedSource.value=null;sourceDialog.value=true;}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"题单素材加载失败");}finally{sourceLoading.value=false;}}
function publishSelected(){if(!selectedSource.value){ElMessage.warning("请选择题单素材");return;}void router.push({path:url(`/practices/${selectedSource.value}/publish`),query:{courseId:String(courseId.value)}});}
watch(()=>[route.fullPath,page.value,keyword.value] as const,()=>{void load();},{immediate:true});
</script>

<template>
  <section class="course-management page-container">
    <el-alert v-if="error" type="error" :title="error" :closable="false" show-icon><template #default><el-button link type="primary" @click="load">重试</el-button></template></el-alert>
    <template v-if="!courseId"><el-card shadow="never"><div class="course-toolbar management-inline-toolbar"><el-input v-model="keyword" clearable placeholder="搜索课程名称" @keyup.enter="page=1;load()"/><el-button @click="page=1;load()">搜索</el-button><div class="management-card-actions"><header class="course-heading"><div class="heading-actions"><el-button v-if="!courseId" type="primary" @click="openEditor()">创建课程</el-button><template v-else><el-button @click="router.push(url('/courses'))">返回课程列表</el-button><el-button v-if="course" @click="openEditor(course)">编辑课程</el-button></template></div></header></div></div><el-alert type="info" :closable="false" title="每门课程可关联多个班级，关联班级的学生自动加入并共享课程题单。"/><el-table v-loading="loading" :data="courseRows" stripe row-key="id" class="course-table"><el-table-column prop="title" label="课程名称" min-width="180"/><el-table-column prop="term" label="学期" min-width="130"><template #default="{row}">{{row.term||"-"}}</template></el-table-column><el-table-column label="关联班级" min-width="220"><template #default="{row}"><el-tag v-for="item in row.classes" :key="item.id" size="small">{{item.name}}</el-tag><span v-if="!row.classes?.length">未设置</span></template></el-table-column><el-table-column prop="studentCount" label="学生数" width="100"/><el-table-column prop="practiceCount" label="题单数" width="100"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.status==='ACTIVE'?'success':row.status==='ARCHIVED'?'info':'warning'">{{row.status==='ACTIVE'?'进行中':row.status==='ARCHIVED'?'已归档':'草稿'}}</el-tag></template></el-table-column><el-table-column label="操作" width="210" fixed="right"><template #default="{row}"><el-button link type="primary" @click="router.push(url(`/courses/${row.id}`))">管理课程</el-button><el-button link @click="openEditor(row)">编辑</el-button><el-button v-if="row.status!=='ARCHIVED'" link type="warning" @click="archive(row)">归档</el-button></template></el-table-column></el-table><div class="course-pagination"><Pagination v-model:page="page" :limit="20" :total="total"/></div></el-card></template>
    <template v-else><el-card v-loading="loading" shadow="never"><template #header><div class="management-card-heading"><div class="management-card-actions"><header class="course-heading"><div class="heading-actions"><el-button v-if="!courseId" type="primary" @click="openEditor()">创建课程</el-button><template v-else><el-button @click="router.push(url('/courses'))">返回课程列表</el-button><el-button v-if="course" @click="openEditor(course)">编辑课程</el-button></template></div></header></div></div></template><div v-if="course" class="course-summary"><div class="summary-tags"><el-tag :type="course.status==='ACTIVE'?'success':course.status==='ARCHIVED'?'info':'warning'">{{course.status==='ACTIVE'?'进行中':course.status==='ARCHIVED'?'已归档':'草稿'}}</el-tag><el-tag v-for="item in course.classes??[]" :key="item.id">{{item.name}}</el-tag><span>{{course.term||"未设置学期"}}</span><span>{{course.studentCount}} 名学生自动加入</span></div><p>{{course.description||"暂无课程介绍"}}</p></div></el-card><el-card shadow="never"><template #header><div class="section-header"><strong>课程题单</strong><el-button type="primary" :disabled="course?.status!=='ACTIVE'||!course?.classIds?.length" @click="loadSources()">添加题单</el-button></div></template><el-table :data="publications" stripe><el-table-column prop="displayOrder" label="顺序" width="80"/><el-table-column prop="title" label="题单名称" min-width="180"/><el-table-column label="题目数" width="100"><template #default="{row}">{{row.problems?.length??0}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag>{{row.status==='PUBLISHED'?'已发布':'已归档'}}</el-tag></template></el-table-column><el-table-column label="开放时间" min-width="220"><template #default="{row}">{{row.startTime&&row.endTime?`${formatDisplayDateTime(row.startTime)} 至 ${formatDisplayDateTime(row.endTime)}`:'未设置'}}</template></el-table-column><el-table-column label="操作" width="175"><template #default="{row}"><el-button link @click="router.push(url(`/practices/publications/${row.id}/report?courseId=${courseId}`))">做题信息</el-button><el-button link type="primary" @click="router.push(url(`/practices/publications/${row.id}/edit?courseId=${courseId}`))">编辑题单</el-button></template></el-table-column></el-table><el-empty v-if="!publications.length" description="暂无已发布题单"/></el-card><el-card shadow="never"><template #header><div class="section-header"><strong>班级学习情况</strong><el-select v-model="classFilter" clearable placeholder="全部关联班级" style="width:220px"><el-option v-for="item in course?.classes??[]" :key="item.id" :value="item.id" :label="item.name"/></el-select></div></template><el-table :data="filteredStudents" stripe><el-table-column prop="className" label="班级" min-width="130"/><el-table-column prop="studentNo" label="学号" min-width="130"/><el-table-column prop="displayName" label="学生姓名" min-width="140"/><el-table-column prop="submissionCount" label="提交次数" width="100"/><el-table-column prop="solvedCount" label="通过题数" width="100"/><el-table-column label="完成题单" width="120"><template #default="{row}">{{row.completedPractices}} / {{report?.practiceCount??0}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.submissionCount?'success':'warning'">{{row.submissionCount?'已提交':'未提交'}}</el-tag></template></el-table-column></el-table></el-card></template>
    
<el-dialog class="qoj-management-dialog" v-model="dialogOpen" :title="editing?'编辑课程':'创建课程'" width="620px"><el-form ref="formRef" :model="form" label-position="top"><el-form-item label="课程名称" required><el-input v-model="form.title" maxlength="200"/></el-form-item><div class="form-two-col"><el-form-item label="学期"><el-input v-model="form.term" placeholder="例如：2026 秋季"/></el-form-item><el-form-item label="课程状态"><el-select v-model="form.status"><el-option label="草稿" value="DRAFT"/><el-option label="进行中" value="ACTIVE"/><el-option label="已归档" value="ARCHIVED"/></el-select></el-form-item></div><el-form-item label="关联班级" extra="关联班级学生自动加入课程；移除后会失去访问权，历史提交保留。"><el-select v-model="form.classIds" multiple filterable clearable placeholder="选择一个或多个班级"><el-option v-for="item in classes" :key="item.id" :value="item.id" :label="item.name"/></el-select></el-form-item><el-form-item label="课程介绍"><el-input v-model="form.description" type="textarea" :rows="4" maxlength="10000"/></el-form-item></el-form><template #footer><el-button @click="dialogOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveCourse">保存课程</el-button></template></el-dialog>
    <el-dialog class="qoj-management-dialog" v-model="sourceDialog" title="添加课程题单" width="560px"><p>选用题单素材并发布到当前课程，关联班级学生即可访问。</p><el-select v-model="selectedSource" v-loading="sourceLoading" filterable placeholder="选择题单素材" style="width:100%"><el-option v-for="item in sources" :key="item.id" :value="item.id" :label="item.title"/></el-select><div class="source-pager"><el-button :disabled="sourcePage<=1" @click="loadSources(sourcePage-1)">上一页</el-button><span>第 {{sourcePage}} 页</span><el-button :disabled="sourcePage*50>=sourceTotal" @click="loadSources(sourcePage+1)">下一页</el-button><el-button link type="primary" @click="router.push({path:url('/practices/new'),query:{courseId:String(courseId)}})">创建新题单</el-button></div><template #footer><el-button @click="sourceDialog=false">取消</el-button><el-button type="primary" @click="publishSelected">设置并发布</el-button></template></el-dialog>
  </section>
</template>

<style scoped>
.course-management{display:flex;flex-direction:column;gap:16px}.course-heading,.section-header,.course-pagination{display:flex;align-items:center;justify-content:space-between;gap:12px}.course-heading h1{margin:0;font-size:22px}.course-heading p{margin:6px 0 0;color:var(--el-text-color-secondary);font-size:13px}.heading-actions{display:flex;align-items:center;gap:8px}.course-toolbar{display:flex;gap:9px;margin-bottom:12px}.course-toolbar .el-input{max-width:300px}.course-table{margin-top:12px}.course-pagination{margin-top:14px}.course-summary p{margin:14px 0 0;color:var(--el-text-color-secondary);white-space:pre-wrap}.summary-tags{display:flex;flex-wrap:wrap;align-items:center;gap:8px;color:var(--el-text-color-secondary);font-size:13px}.source-pager{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:15px}.form-two-col{display:grid;grid-template-columns:1fr 1fr;gap:12px}.el-select{width:100%}.section-header>strong{font-size:15px}@media(max-width:700px){.course-heading{align-items:flex-start;flex-direction:column}.heading-actions{flex-wrap:wrap}.course-pagination{align-items:flex-start;flex-direction:column}.form-two-col{grid-template-columns:1fr}}
</style>
